fn is_non_prime(n: u64) -> bool {
    // Handle n = 2 separately (prime, so return false)
    if n == 2 {
        return false;
    }
    
    // Check if n is even (except 2 which we already handled)
    if n % 2 == 0 {
        return true;
    }
    
    // Only check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    
    let mut divisor = 3;
    while divisor <= limit {
        if n % divisor == 0 {
            return true;
        }
        divisor += 2; // Skip even divisors
    }
    
    false
}